#[inline]
pub fn sample_petal_pigment(petal: usize, u_norm: f32, v_signed: f32) -> [f32; 3] {
    let p = petal.min(PETAL_COUNT - 1);
    let u = u_norm.clamp(0.0, 1.0) * (LUT_U - 1) as f32;
    let v = ((v_signed.clamp(-1.0, 1.0) * 0.5) + 0.5) * (LUT_V - 1) as f32;
    let u0 = (u.floor() as usize).min(LUT_U - 2);
    let v0 = (v.floor() as usize).min(LUT_V - 2);
    let fu = u - u0 as f32;
    let fv = v - v0 as f32;
    let idx = |iu: usize, iv: usize| -> [f32; 3] {
        let base = ((p * LUT_U + iu) * LUT_V + iv) * 3;
        [PETAL_LUT[base] as f32, PETAL_LUT[base + 1] as f32, PETAL_LUT[base + 2] as f32]
    };
    let c00 = idx(u0, v0);
    let c10 = idx(u0 + 1, v0);
    let c01 = idx(u0, v0 + 1);
    let c11 = idx(u0 + 1, v0 + 1);
    let mut out = [0.0f32; 3];
    for c in 0..3 {
        let a = c00[c] + (c10[c] - c00[c]) * fu;
        let b = c01[c] + (c11[c] - c01[c]) * fu;
        out[c] = a + (b - a) * fv;
    }
    out
}
